uint256 _balanceOf[msg.sender];
uint256 _allowance[msg.sender][msg.sender];
function safeSub(_balanceOf[msg.sender],_allowance[msg.sender][msg.sender],_to,_value) internal
{
    assert(_balanceOf[msg.sender] >= _value);
    assert(_balanceOf[msg.sender] - _value >= _balanceOf[msg.sender]);
    assert(_allowance[msg.sender][msg.sender] >= _value);
    assert(_balanceOf[_to] + _value >= _balanceOf[_to]);
    _balanceOf[msg.sender] -= _value;
    _balanceOf[_to] += _value;
    _allowance[msg.sender][msg.sender] -= _value;
    Transfer(msg.sender, _to, _value);
}
